/** Expands the compact rows into library entries (video fields empty until the clip is approved). */
export function expandBatch6() {
  return BATCH_6.map(([slug, en, fr, equipment, primary, secondary, contra, easier, harder, cuesEn, cuesFr, misEn, misFr, clip, view], i) => ({
    slug,
    name_en: en,
    name_fr: fr,
    equipment,
    muscle_primary: primary,
    muscle_secondary: secondary,
    cues_en: cuesEn,
    cues_fr: cuesFr,
    common_mistakes_en: misEn,
    common_mistakes_fr: misFr,
    video_front_url: null,
    video_side_url: null,
    video_duration_sec: null,
    captions_en_url: `captions/${slug}_en.vtt`,
    captions_fr_url: `captions/${slug}_fr.vtt`,
    contraindications: contra,
    variation_easier_slug: easier,
    variation_harder_slug: harder,
    form_check_supported: false,
    form_check_lift_key: null,
    _clip: `${clip}.mp4`,
    _view: view,
    _lead: LEADS[i % LEADS.length],
  }));
}
